#!/usr/bin/env bash
# СУДИТ: hooks/lib/backfill-replay-one.sh
# probe_D1205 — в реплее одной расшифровки поручение хода k видно детектору в ходе k+1 (ADR-010, плечо A замера
# `scripts/ab-authorization-replay.sh`). Воркер давал каждому ходу свой SID, файл авторизации искался по SID, и на каждом
# ходе состояния «не было»: плечо A уходило в одношаговую проверку и совпадало с плечом B по построению (1 ноября 2026,
# скептик opus по 42f31ef8, D1154 M3).
# Фикстура: «исправь…» → правка → «дальше» → правка → «спасибо…». Суд — по пути решения в событии: правку после «дальше»
# плечо A судит состоянием задачи (маркер `auth:`), плечо B — одношаговой проверкой (`prior:`).
# Красная (1), пока плечо A не судит состоянием ни одной правки; 2 — рамка не собралась (плечо B не дало событий).
R="${CLAUDSOUL_REPO:-$(cd "$(dirname "$0")/../../.." && pwd)}"
W="$R/hooks/lib/backfill-replay-one.sh"
[ -f "$W" ] || exit 2
command -v jq >/dev/null 2>&1 || exit 2
T=$(mktemp -d "${TMPDIR:-/tmp}/probe-D1205.XXXXXX") || exit 2
trap 'rm -rf "$T"' EXIT
F="$T/t.jsonl"
u() { jq -cn --arg ts "$1" --arg t "$2" '{type:"user",timestamp:$ts,message:{role:"user",content:[{type:"text",text:$t}]}}'; }
a() { jq -cn --arg ts "$1" --arg t "$2" '{type:"assistant",timestamp:$ts,message:{role:"assistant",content:[{type:"text",text:$t},{type:"tool_use",name:"Edit",id:"x",input:{}}]}}'; }
{
    u 2026-01-01T10:00:00Z "исправь функцию разбора дат в модуле отчётов"
    a 2026-01-01T10:00:05Z "Поправил разбор."
    u 2026-01-01T10:01:00Z "дальше"
    a 2026-01-01T10:01:05Z "Поправил вывод."
    u 2026-01-01T10:02:00Z "спасибо, посмотрю позже обязательно"
} > "$F"
arm() { AUTH_ONESHOT_ONLY="$1" BACKFILL_TMP="$T" bash "$W" "$F" 2>/dev/null; }
A=$(arm 0); B=$(arm 1)
# Положительный контроль рамки: одношаговая проверка видит обе правки под поручением.
[ "$(grep -c '"type":"solicited"' <<< "$B")" -ge 2 ] || { echo "рамка: плечо B не дало двух событий «под поручением»" >&2; exit 2; }
# Суд — по поручению САМОГО хода k («дальше»), а не по любому `auth:`: подложенное чужое состояние проходило бы
# (скептик opus по eeb89ab4, L2).
grep -q "solicited:'auth:continuation:дальше:Edit'" <<< "$A" && { echo "плечо A судит правку состоянием задачи — поручение перешло между ходами"; exit 0; }
echo "плечо A ни одной правки состоянием не судило — каждый ход реплея начинает сессию заново"
exit 1
